/** @scope spec://codkit/modules/vscode-extension/PROP-002#VSX-OWN-ROOT */
// Area 2: where own code lives, what a fresh pass may delete and what a patch
// may never target.
//
// The own root of this family lies under `<extensionRoot>/src/`: the bundler
// reaches a module only from the activation entry of the extension, and the
// type check, the lint and the tests of an extension are anchored at its
// `src/` (##VSX-OWN-ROOT). The type owns that one directory and nothing a build
// writes is inside it - the bundler writes into `dist/` or `out/` of the
// extension root (##VSX-ONE-OWNED-DIRECTORY).
import { oneOwnedDirectory } from '@codkit/type-api';
/**
 * ##VSX-FORBIDDEN-TARGETS: the lockfiles of the four package managers, at any
 * depth - a pattern without a slash matches at every level. A lockfile is
 * regenerated by the install, so a patch of it is overwritten by the next
 * install. The overlay targets of PROP-003 are forbidden too, and the engine
 * adds them from the layers area rather than having them restated here.
 */
export const LOCKFILES = [
    'package-lock.json',
    'npm-shrinkwrap.json',
    'pnpm-lock.yaml',
    'yarn.lock',
    'bun.lock',
    'bun.lockb'
];
export const FORBIDDEN_PATCH_TARGETS = LOCKFILES;
/** The directory under the extension root that anchors the sources of an extension. */
export const SOURCE_DIR = 'src';
/** Whether a value is a directory path from the tree root, POSIX, with no escape. */
export function isTreePath(value) {
    if (value === '' || value.startsWith('/') || value.endsWith('/') || value.includes('\\')) {
        return false;
    }
    return value.split('/').every((segment) => segment !== '' && segment !== '.' && segment !== '..');
}
/**
 * A path inside the extension root, from the tree root. The extension root of a
 * repository that is one extension is `.`, and a path under it is simply the
 * relative path: no segment `.` ever reaches the engine, whose pattern checks
 * refuse one.
 */
export function treePath(extensionRoot, relative) {
    return extensionRoot === '.' ? relative : `${extensionRoot}/${relative}`;
}
/**
 * A gitignore-style pattern anchored at the extension root. A pattern with an
 * inner slash is anchored by itself; one of a root extension gets the leading
 * slash, so that `dist/` of the extension root never protects a `dist/` deeper
 * in the tree (`spec://codkit/modules/codkit/PROP-011#CLEANUP-WHITELIST-CONTENT`).
 */
export function anchoredPattern(extensionRoot, relative) {
    return extensionRoot === '.' ? `/${relative}` : `${extensionRoot}/${relative}`;
}
/** `<extensionRoot>/src`, from the tree root. */
export function sourceRootOf(extensionRoot) {
    return treePath(extensionRoot, SOURCE_DIR);
}
/**
 * ##VSX-OWN-ROOT: a directory strictly under `<extensionRoot>/src/`. The
 * detail names the constraint, and the engine turns it into `CK-E-CONFIG`.
 */
export function ownRootProblem(ownRoot, extensionRoot) {
    const sourceRoot = sourceRootOf(extensionRoot);
    if (ownRoot === '') {
        return `must be a path from the tree root under ${sourceRoot}/`;
    }
    if (ownRoot.startsWith('/') || ownRoot.endsWith('/')) {
        return 'must be written without a leading or trailing slash';
    }
    if (ownRoot.includes('\\')) {
        return 'must use forward slashes';
    }
    if (ownRoot.split('/').some((segment) => segment === '' || segment === '.' || segment === '..')) {
        return 'must not contain an empty, dot or dot-dot segment';
    }
    if (!ownRoot.startsWith(`${sourceRoot}/`)) {
        return (`must lie under ${sourceRoot}/: the bundler of this family reaches a module only from the activation entry of the extension, ` +
            'and its type check, lint and tests are anchored at that directory');
    }
    return null;
}
/**
 * ##VSX-CLEANUP-WHITELIST: the untracked outputs a fresh pass keeps. Every
 * entry is written by an install, a build, a packager or a test host and is
 * worth keeping; everything else untracked is removed, under the engine's
 * semantics. The family's list first, then what the patch set adds.
 */
export function cleanupWhitelistOf(config) {
    return [
        'node_modules/',
        anchoredPattern(config.extensionRoot, 'dist/'),
        anchoredPattern(config.extensionRoot, 'out/'),
        anchoredPattern(config.extensionRoot, '*.vsix'),
        '.vscode-test/',
        '**/.turbo/',
        '.eslintcache',
        '*.tsbuildinfo',
        ...(config.cleanupWhitelist ?? [])
    ];
}
/**
 * ##VSX-ONE-OWNED-DIRECTORY: the own root alone, with no build outputs inside
 * it, and no extension path - an extension has no extension host of its own
 * (##VSX-NO-OWN-EXTENSION-PATH).
 */
export function makeLayout(config) {
    return {
        ownRootProblem: (ownRoot) => ownRootProblem(ownRoot, config.extensionRoot),
        ownRoots: (layoutConfig) => oneOwnedDirectory(layoutConfig.ownRoot),
        ownExtensionPath: () => null,
        cleanupWhitelist: cleanupWhitelistOf(config),
        forbiddenPatchTargets: FORBIDDEN_PATCH_TARGETS
    };
}
